Here's a basic implementation of a singly linked list:

```js
class Node {
  constructor(data) {
    this.data = data;
    this.next = null;
  }
}

class LinkedList {
  constructor() {
    this.head = null;
  }

  append(data) {
    const newNode = new Node(data);
    if (!this.head) {
      this.head = newNode;
      return;
    }
    let current = this.head;
    while (current.next) {
      current = current.next;
    }
    current.next = newNode;
  }

  print() {
    let current = this.head;
    let result = "";
    while (current) {
      result += current.data + " -> ";
      current = current.next;
    }
    console.log(result + "null");
  }
}

const list = new LinkedList();
list.append(10);
list.append(20);
list.append(30);
list.print(); // 10 -> 20 -> 30 -> null
```

Let's implement insertion at the beginning and deletion by value:

```js
class LinkedList {
  constructor() {
    this.head = null;
  }

  insertAtBeginning(data) {
    const newNode = new Node(data);
    newNode.next = this.head;
    this.head = newNode;
  }

  deleteByValue(data) {
    if (!this.head) return;
    if (this.head.data === data) {
      this.head = this.head.next;
      return;
    }
    let current = this.head;
    while (current.next && current.next.data !== data) {
      current = current.next;
    }
    if (current.next) {
      current.next = current.next.next;
    }
  }
}

const list = new LinkedList();
list.insertAtBeginning(30);
list.insertAtBeginning(20);
list.insertAtBeginning(10);
list.deleteByValue(20);
list.print(); // 10 -> 30 -> null
```

Traversal means visiting every node. Searching looks for a particular value.

```js
search(value) {
  let current = this.head;
  while (current) {
    if (current.data === value) return true;
    current = current.next;
  }
  return false;
}

// Usage:
console.log(list.search(30)); // true
console.log(list.search(40)); // false
```

This is a classic interview question:

```js
reverse() {
  let prev = null;
  let current = this.head;
  while (current) {
    let nextNode = current.next;
    current.next = prev;
    prev = current;
    current = nextNode;
  }
  this.head = prev;
}

list.reverse();
list.print(); // prints the reversed list
```

```js
class DoublyNode {
  constructor(data) {
    this.data = data;
    this.prev = null;
    this.next = null;
  }
}

class DoublyLinkedList {
  constructor() {
    this.head = null;
    this.tail = null;
  }

  append(data) {
    const newNode = new DoublyNode(data);
    if (!this.head) {
      this.head = this.tail = newNode;
    } else {
      this.tail.next = newNode;
      newNode.prev = this.tail;
      this.tail = newNode;
    }
  }

  printForward() {
    let current = this.head;
    let output = "";
    while (current) {
      output += current.data + " <-> ";
      current = current.next;
    }
    console.log(output + "null");
  }

  printBackward() {
    let current = this.tail;
    let output = "";
    while (current) {
      output += current.data + " <-> ";
      current = current.prev;
    }
    console.log(output + "null");
  }
}

const dlist = new DoublyLinkedList();
dlist.append(1);
dlist.append(2);
dlist.append(3);
dlist.printForward();  // 1 <-> 2 <-> 3 <-> null
dlist.printBackward(); // 3 <-> 2 <-> 1 <-> null
```
